composeOverride:
# Generated by McHarbor App Store
services:
  {{serviceName}}:
    image: {{image}}
    container_name: {{containerName}}
    restart: unless-stopped
{{ports}}
    environment:
      TZ: {{env.TZ}}
      DATABASE_URL: "postgresql://langfuse:{{env.POSTGRES_PASSWORD}}@{{serviceName}}-postgres:5432/langfuse"
      NEXTAUTH_SECRET: {{env.NEXTAUTH_SECRET}}
      SALT: {{env.SALT}}
      NEXTAUTH_URL: {{env.NEXTAUTH_URL}}
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
    depends_on:
      - {{serviceName}}-postgres
  {{serviceName}}-postgres:
    image: postgres:16-alpine
    container_name: {{serviceName}}-postgres
    restart: unless-stopped
    environment:
      POSTGRES_USER: langfuse
      POSTGRES_PASSWORD: {{env.POSTGRES_PASSWORD}}
      POSTGRES_DB: langfuse
    volumes:
      - {{appDataPath}}/postgres:/var/lib/postgresql/data
